<h1><?= te('Client invoices and attendance reports') ?></h1><p class="sub"><?= te('Generate a frozen invoice from approved weekly sheets. Already invoiced sheets cannot be billed twice. Print or save the report for your existing email process.') ?></p><form class="card row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="generate"><div><label><?= te('First week-ending date') ?></label><input name="starts_on" type="date" required></div><div><label><?= te('Last week-ending date') ?></label><input name="ends_on" type="date" required></div><button class="btn"><?= te('Generate draft invoice') ?></button></form>
<?php if($invoice): ?><div class="card invoice-print"><h2><?= e($invoice['reference']) ?> · <?= e($invoice['status']) ?></h2><p><?= e(($job['client_name'] ?? '').' · '.$job['title'].' · '.$invoice['starts_on'].' → '.$invoice['ends_on']) ?></p><table><tr><th><?= te('Worker') ?></th><th><?= te('Week') ?></th><th><?= te('Hours') ?></th><th><?= te('Rate') ?></th><th><?= te('Amount') ?></th></tr><?php foreach(json_decode($invoice['details_json'],true) as $l): ?><tr><td><?= e($l['worker']) ?></td><td><?= e($l['week']) ?></td><td><?= e($l['hours']) ?></td><td><?= money($l['rate']) ?></td><td><?= money($l['amount']) ?></td></tr><?php endforeach; ?></table><h2 style="margin-top:20px">Total: <?= money($invoice['total']) ?></h2><button class="btn" onclick="window.print()"><?= te('Print / save as PDF') ?></button><p class="muted"><?= te('Labour invoice only. Tax, credits, reimbursable vendor charges and contract-specific billing adjustments require accounting review.') ?></p></div><?php endif; ?>
<div class="card"><h2><?= te('Invoice register') ?></h2><?php foreach($invoices as $i): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="invoice_id" value="<?= (int)$i['id'] ?>"><a href="/client-invoices?id=<?= (int)$i['id'] ?>"><?= e($i['reference']) ?></a><span><?= money($i['total']) ?> · <?= e($i['status']) ?></span><?php if($i['status']==='draft'): ?><input type="hidden" name="do" value="issue"><button class="btn sm"><?= te('Mark issued') ?></button><?php elseif($i['status']==='issued'): ?><input type="hidden" name="do" value="paid"><button class="btn sm"><?= te('Mark payment received') ?></button><?php endif; ?></form><?php endforeach; ?></div><div class="card"><h2><?= te('Approved daily attendance') ?></h2><table><tr><th><?= te('Date') ?></th><th><?= te('Workers on site') ?></th><th><?= te('Approved hours') ?></th></tr><?php foreach($attendance as $a): ?><tr><td><?= e($a['work_date']) ?></td><td><?= (int)$a['workers'] ?></td><td><?= e($a['hours']) ?></td></tr><?php endforeach; ?></table></div><style>@media print{.top,.nav,.product-note,form,button,.sub{display:none!important}.wrap{margin:0;padding:0}.card{box-shadow:none}.wrap>.card:not(.invoice-print){display:none}}</style>